/**
 * Clawd sprites: Claude Code's orange mascot as the agents' character.
 *
 * The one base sheet (clawd-sheet.json, generated by
 * scripts/generate-clawd-sprites.mjs in the chibi sheets' 112×96 format) is
 * sliced into frames here, then per agent: the eyes shut for a blink, the
 * body is tinted for its repo (CLAWD_TINTS), and its accessory is composed on
 * top — in the frame, so it follows direction, the walk bob, the sitting
 * offset, the hover outline and the matrix effect for free. Everything but
 * the cache is pure, so the placement unit-tests in the Node runner.
 */

import {
  CLAWD_ACCESSORY_COLORS,
  CLAWD_BODY_COLOR,
  CLAWD_EYE_COLOR,
  CLAWD_TINTS,
} from '../../constants.js';
import type { ClawdAccessory } from '../agentLook.js';
import { adjustSprite } from '../colorize.js';
import type { SpriteData } from '../types.js';
import sheetData from './clawd-sheet.json';
import type { CharacterSprites, LoadedCharacterData } from './spriteData.js';
import { buildCharacterSprites } from './spriteData.js';

export type SheetDirection = 'down' | 'up' | 'right';

interface ClawdSheetJson {
  frameW: number;
  frameH: number;
  frames: number;
  directions: readonly string[];
  palette: Record<string, string>;
  rows: readonly string[];
}

/** The sheet's frame layout, as the engine expects it. */
export const CLAWD_FRAME_W = 16;
export const CLAWD_FRAME_H = 32;
export const CLAWD_FRAMES_PER_ROW = 7;
export const CLAWD_DIRECTIONS: readonly SheetDirection[] = ['down', 'up', 'right'];

// ── The base sheet ─────────────────────────────────────────────

let baseSheet: LoadedCharacterData | null = null;

/** Slice the palette-keyed sheet into frames (same cut as decodeCharacterPng). */
export function decodeClawdSheet(sheet: ClawdSheetJson = sheetData): LoadedCharacterData {
  const out: LoadedCharacterData = { down: [], up: [], right: [] };
  CLAWD_DIRECTIONS.forEach((dir, di) => {
    for (let f = 0; f < CLAWD_FRAMES_PER_ROW; f++) {
      const frame: SpriteData = [];
      for (let y = 0; y < CLAWD_FRAME_H; y++) {
        const row = sheet.rows[di * CLAWD_FRAME_H + y] ?? '';
        const px: string[] = [];
        for (let x = 0; x < CLAWD_FRAME_W; x++) {
          const key = row[f * CLAWD_FRAME_W + x] ?? '.';
          px.push(key === '.' ? '' : (sheet.palette[key] ?? ''));
        }
        frame.push(px);
      }
      out[dir].push(frame);
    }
  });
  return out;
}

function base(): LoadedCharacterData {
  baseSheet ??= decodeClawdSheet();
  return baseSheet;
}

// ── Frame helpers (pure) ───────────────────────────────────────

/** The first row of a frame with any pixel: the top of the body. -1 when empty. */
export function bodyTopRow(frame: SpriteData): number {
  return frame.findIndex((row) => row.some((px) => px !== ''));
}

/** The eyes' pixels of a base frame (by the sheet's unique eye colour). */
export function eyePixels(frame: SpriteData): Array<{ x: number; y: number }> {
  const out: Array<{ x: number; y: number }> = [];
  frame.forEach((row, y) =>
    row.forEach((px, x) => {
      if (px === CLAWD_EYE_COLOR) out.push({ x, y });
    }),
  );
  return out;
}

/** The frame with its eyes shut: eye pixels take the body colour. */
export function blinkFrame(frame: SpriteData): SpriteData {
  return frame.map((row) => row.map((px) => (px === CLAWD_EYE_COLOR ? CLAWD_BODY_COLOR : px)));
}

/** One pixel of an accessory, in frame coordinates. */
export interface AccessoryPixel {
  x: number;
  y: number;
  color: string;
}

/** Accessory art: rows of 16 characters; row 0 sits `dy` rows from the body's top row. */
interface AccessoryArt {
  dy: number;
  rows: readonly string[];
}

const C = CLAWD_ACCESSORY_COLORS;
const LEGEND: Record<string, string> = {
  K: C.outline,
  C: C.cap,
  B: C.capBrim,
  H: C.headset,
  P: C.headsetPad,
  M: C.mic,
  R: C.beanie,
  D: C.beanieBand,
  W: C.pompom,
  O: C.bow,
  N: C.bowKnot,
  G: C.glasses,
  A: C.antenna,
  Y: C.antennaBall,
};

/**
 * The accessories by direction (left is the mirrored right frame). The body
 * is 12 wide (cols 2-13) from the front and back, 10 wide (cols 3-12) from
 * the side, with its top outline row on cols 4-11 / 5-10. Glasses are drawn
 * around the eyes instead (glassesPixels) so they follow a reading Clawd's
 * downcast eyes.
 */
const ACCESSORY_ART: Record<
  Exclude<ClawdAccessory, 'glasses'>,
  Record<SheetDirection, AccessoryArt | null>
> = {
  cap: {
    down: {
      dy: -2,
      rows: ['.....CCCCCC.....', '...KCCCCCCCCK...', '..KCCCCCCCCCCK..', '..BBBBBBBBBBBB..'],
    },
    up: {
      dy: -2,
      rows: ['.....CCCCCC.....', '...KCCCCCCCCK...', '..KCCCCCCCCCCK..'],
    },
    right: {
      dy: -2,
      rows: ['.....CCCCCC.....', '...KCCCCCCCCK...', '...KCCCCCCCCK...', '...BBBBBBBBBBBB.'],
    },
  },
  headset: {
    down: {
      dy: -1,
      rows: [
        '...HHHHHHHHHH...',
        '................',
        '................',
        '................',
        'HP............PH',
        'HH............HH',
      ],
    },
    up: {
      dy: -1,
      rows: [
        '...HHHHHHHHHH...',
        '................',
        '................',
        '................',
        'HH............HH',
        'HH............HH',
      ],
    },
    right: {
      dy: -1,
      rows: [
        '....HHHHHHHH....',
        '................',
        '................',
        '................',
        '....HP..........',
        '....HH..........',
        '......MMMMMK....',
      ],
    },
  },
  beanie: {
    down: {
      dy: -3,
      rows: [
        '......KWWK......',
        '....KRRRRRRK....',
        '...KRRRRRRRRK...',
        '..KRRRRRRRRRRK..',
        '..KDDDDDDDDDDK..',
      ],
    },
    up: {
      dy: -3,
      rows: [
        '......KWWK......',
        '....KRRRRRRK....',
        '...KRRRRRRRRK...',
        '..KRRRRRRRRRRK..',
        '..KDDDDDDDDDDK..',
      ],
    },
    right: {
      dy: -3,
      rows: [
        '.....KWWK.......',
        '.....KRRRRK.....',
        '....KRRRRRRK....',
        '...KRRRRRRRRK...',
        '...KDDDDDDDDK...',
      ],
    },
  },
  bow: {
    down: { dy: -2, rows: ['.........OO.OO..', '.........OONOO..', '.........OO.OO..'] },
    up: { dy: -2, rows: ['..OO.OO.........', '..OONOO.........', '..OO.OO.........'] },
    right: { dy: -2, rows: ['...OO.OO........', '...OONOO........', '...OO.OO........'] },
  },
  antenna: {
    down: {
      dy: -4,
      rows: ['.......YY.......', '.......YY.......', '........A.......', '........A.......'],
    },
    up: {
      dy: -4,
      rows: ['.......YY.......', '.......YY.......', '........A.......', '........A.......'],
    },
    right: {
      dy: -4,
      rows: ['......YY........', '......YY........', '.......A........', '.......A........'],
    },
  },
};

/**
 * Where an accessory's pixels land on a frame whose body starts on row
 * `bodyTop`, for a direction of the sheet. Pure: direction and body top in,
 * frame-coordinate pixels out — so the overlay follows the walk bob (the
 * body top moves) and the sitting pose (it moves more) by construction.
 */
export function accessoryPixels(
  kind: Exclude<ClawdAccessory, 'glasses'>,
  dir: SheetDirection,
  bodyTop: number,
): AccessoryPixel[] {
  const art = ACCESSORY_ART[kind][dir];
  if (!art || bodyTop < 0) return [];
  const out: AccessoryPixel[] = [];
  art.rows.forEach((row, i) => {
    const y = bodyTop + art.dy + i;
    for (let x = 0; x < row.length; x++) {
      const color = LEGEND[row[x]];
      if (color) out.push({ x, y, color });
    }
  });
  return out;
}

/**
 * Glasses: a round 1 px rim around each eye (the 2×2 eye's four sides, no
 * corners, so two lenses meet at a bridge instead of merging into a visor),
 * plus, from the side, a temple reaching back along the head from the lens.
 * Nothing from behind. Follows the eyes, so a reading Clawd keeps them on.
 */
export function glassesPixels(eyes: ReadonlyArray<{ x: number; y: number }>): AccessoryPixel[] {
  if (eyes.length === 0) return [];
  // Group the eye pixels into eyes (2×2 blobs) by their top-left corner.
  const minX = Math.min(...eyes.map((p) => p.x));
  const maxX = Math.max(...eyes.map((p) => p.x));
  const minY = Math.min(...eyes.map((p) => p.y));
  const twoEyes = maxX - minX > 1;
  const lenses: Array<{ x0: number; x1: number }> = twoEyes
    ? [
        { x0: minX, x1: minX + 1 },
        { x0: maxX - 1, x1: maxX },
      ]
    : [{ x0: minX, x1: maxX }];
  const seen = new Set<string>();
  const out: AccessoryPixel[] = [];
  const push = (x: number, y: number) => {
    const k = `${x},${y}`;
    if (seen.has(k) || x < 0 || x >= CLAWD_FRAME_W || y < 0) return;
    seen.add(k);
    out.push({ x, y, color: C.glasses });
  };
  for (const lens of lenses) {
    for (let x = lens.x0; x <= lens.x1; x++) {
      push(x, minY - 1);
      push(x, minY + 2);
    }
    for (let y = minY; y <= minY + 1; y++) {
      push(lens.x0 - 1, y);
      push(lens.x1 + 1, y);
    }
  }
  if (!twoEyes) {
    // Side view: the temple runs back from the lens to the back of the head.
    for (let x = 4; x < minX - 1; x++) push(x, minY);
  }
  return out;
}

/** The accessory's pixels for a frame of the base sheet. */
export function accessoryFor(
  kind: ClawdAccessory,
  dir: SheetDirection,
  baseFrame: SpriteData,
): AccessoryPixel[] {
  if (kind === 'glasses') return glassesPixels(eyePixels(baseFrame));
  return accessoryPixels(kind, dir, bodyTopRow(baseFrame));
}

/** A copy of the frame with the pixels painted on. */
export function paint(frame: SpriteData, pixels: readonly AccessoryPixel[]): SpriteData {
  const out = frame.map((row) => [...row]);
  for (const p of pixels) {
    if (p.y >= 0 && p.y < out.length && p.x >= 0 && p.x < out[p.y].length) {
      out[p.y][p.x] = p.color;
    }
  }
  return out;
}

// ── The sprite sets ────────────────────────────────────────────

const setCache = new Map<string, CharacterSprites>();

/**
 * The sprite set of a Clawd: tinted for `tint` (an index into CLAWD_TINTS),
 * wearing `accessory` (or none), eyes shut when `blink`. Cached per triple.
 */
export function getClawdSprites(
  tint: number,
  accessory: ClawdAccessory | null,
  blink = false,
): CharacterSprites {
  const t = ((tint % CLAWD_TINTS.length) + CLAWD_TINTS.length) % CLAWD_TINTS.length;
  const key = `${t}:${accessory ?? '-'}:${blink ? 1 : 0}`;
  const cached = setCache.get(key);
  if (cached) return cached;

  const color = CLAWD_TINTS[t];
  const tinted = color.h !== 0 || color.s !== 0 || color.b !== 0;
  const prep = (frame: SpriteData, dir: SheetDirection): SpriteData => {
    let out = blink ? blinkFrame(frame) : frame;
    if (tinted) out = adjustSprite(out, { h: color.h, s: color.s, b: color.b, c: 0 });
    if (accessory) out = paint(out, accessoryFor(accessory, dir, frame));
    return out;
  };
  const src = base();
  const sprites = buildCharacterSprites({
    down: src.down.map((f) => prep(f, 'down')),
    up: src.up.map((f) => prep(f, 'up')),
    right: src.right.map((f) => prep(f, 'right')),
  });
  setCache.set(key, sprites);
  return sprites;
}
